import { usage } from 'argsclopts'
import { getHelpOptions } from './help-options.js'

/**
 * Format the options documented for a command.
 *
 * @param {'npm-run-all' | 'run-p' | 'run-s'} command - The command being documented.
 * @returns {string} The option list generated by argsclopts.
 */
export function getOptionsHelp (command) {
  const singleMode = command !== 'npm-run-all'
  const options = getHelpOptions(singleMode)
  const hidden = new Set()
  if (singleMode) {
    hidden.add('parallel')
    hidden.add('sequential')
  }
  if (command === 'run-s') {
    hidden.add('aggregate-output')
    hidden.add('max-parallel')
    hidden.add('race')
  }

  return usage(Object.fromEntries(
    Object.entries(options)
      .filter(([name]) => !hidden.has(name))
  ), { lineWidth: 79, descriptionColumn: 27 })
}
